# Licensed under a 3-clause BSD style license - see LICENSE.rst
"""Exercise column comparison helpers without requiring compiled extensions.

Run directly with Python from the repository root.  This is a focused check of
source-extracted comparison methods with NumPy subclasses, not a replacement
for the full table tests.
"""
import ast
import operator
from pathlib import Path
import warnings

import numpy as np


source = ast.parse(Path('astropy/table/column.py').read_text())
namespace = {'np': np}
compare = next(node for node in source.body
               if isinstance(node, ast.FunctionDef) and node.name == '_make_compare')
base = next(node for node in source.body
            if isinstance(node, ast.ClassDef) and node.name == 'BaseColumn')
encode = next(node for node in base.body
              if isinstance(node, ast.FunctionDef) and node.name == '_encode_str')
encode.decorator_list = []
exec(compile(ast.Module(body=[compare, encode], type_ignores=[]),
             'astropy/table/column.py', 'exec'), namespace)


class Column(np.ndarray):
    _encode_str = staticmethod(namespace['_encode_str'])

    def __new__(cls, data):
        return np.array(data).view(cls)

    @property
    def data(self):
        return self.view(np.ndarray)


class MaskedColumn(Column, np.ma.MaskedArray):
    def __new__(cls, data, mask=False):
        return np.ma.array(data, mask=mask).view(cls)

    @property
    def data(self):
        out = self.view(np.ma.MaskedArray)
        out._baseclass = np.ndarray
        return out


namespace.update(Column=Column, MaskedColumn=MaskedColumn)
for name in ('eq', 'ne', 'gt', 'lt', 'ge', 'le'):
    setattr(Column, f'__{name}__', namespace['_make_compare'](f'__{name}__'))


def main():
    warnings.simplefilter('error', FutureWarning)
    checks = 0
    failures = []
    for cls1 in (Column, MaskedColumn):
        for cls2 in (Column, MaskedColumn, str, list):
            for values in (['a', 'c'], ['bä', 'dé']):
                rhs = [values[0], values[0]]
                left = cls1([value.encode('utf-8') for value in values])
                right = rhs[0] if cls2 is str else cls2(rhs)
                for name in ('eq', 'ne', 'gt', 'lt', 'ge', 'le'):
                    op = getattr(operator, name)
                    for reverse in (False, True):
                        a, b = (right, left) if reverse else (left, right)
                        x, y = (rhs, values) if reverse else (values, rhs)
                        expected = op(np.array(x), np.array(y))
                        checks += 1
                        try:
                            actual = op(a, b)
                            np.testing.assert_array_equal(actual, expected)
                            assert type(actual) in (np.ndarray, np.ma.MaskedArray)
                        except Exception as exc:
                            failures.append(f'{cls1.__name__}/{cls2.__name__} '
                                            f'{name} reverse={reverse}: {exc!r}')
    for failure in failures:
        print(failure)
    print(f'{checks - len(failures)}/{checks} comparison checks passed; '
          f'NumPy {np.__version__}')
    assert not failures


if __name__ == '__main__':
    main()

